import SwiftUI

// The app's own icons, in place of SF Symbols.
//
// They come from Central Icon System (centralicons.com): line, 2 px stroke,
// medium corners, with the solid set standing in wherever a symbol was
// ".fill". Each is kept under the name of the symbol it replaces, so a call
// site still says "gearshape" and gets the gear from here. Every icon the
// app draws is in the table; the system's symbols stand in only for a name
// that isn't. The keys of a shortcut are drawn apart, from KeyArt, the
// same drawings the pages use (KeyGlyphs).
//
// The artwork is a 24-point square with its shape drawn a little inside it,
// so it is laid out larger than the point size a symbol would have been set
// in: at `scale` times, the two come out about the same weight on screen.

public enum Glyphs {
    /// How much bigger than a symbol's point size the square is drawn.
    public static let scale: CGFloat = 1.35

    private static var made: [String: NSImage] = [:]

    /// The icon for a symbol name, as a template image, or nil when the
    /// system's symbol is still the one used.
    public static func art(_ name: String) -> NSImage? {
        if let hit = made[name] { return hit }
        guard let svg = svgs[name], let image = NSImage(data: Data(svg.utf8)) else { return nil }
        image.isTemplate = true
        made[name] = image
        return image
    }

    /// The icon with its line `stroke` points wide when drawn `side` points
    /// across. Each icon's own line is 2 on its 24 grid, so icons drawn at
    /// different sizes come out in different weights; a row of them that
    /// should read as one set asks for one weight here.
    public static func art(_ name: String, stroke: CGFloat, side: CGFloat) -> NSImage? {
        let key = "\(name) \(stroke) \(side)"
        if let hit = made[key] { return hit }
        let width = String(format: "%.3f", Double(stroke * 24 / side))
        guard let svg = svgs[name]?.replacingOccurrences(of: "stroke-width=\"2\"", with: "stroke-width=\"\(width)\""),
              let image = NSImage(data: Data(svg.utf8)) else { return nil }
        image.isTemplate = true
        made[key] = image
        return image
    }

    /// For AppKit: the icon at the size a symbol set at `size` points would
    /// take, or the system symbol itself when there is no icon for it.
    public static func image(_ name: String, size: CGFloat, weight: NSFont.Weight = .medium) -> NSImage? {
        guard art(name) != nil else {
            return NSImage(systemSymbolName: name, accessibilityDescription: nil)?
                .withSymbolConfiguration(.init(pointSize: size, weight: weight))
        }
        return image(name, side: (size * scale).rounded())
    }

    /// For AppKit: the icon drawn in a square exactly `side` points across.
    public static func image(_ name: String, side: CGFloat) -> NSImage? {
        guard let art = art(name) else { return nil }
        let sized = NSImage(size: NSSize(width: side, height: side), flipped: false) { rect in
            art.draw(in: rect)
            return true
        }
        sized.isTemplate = true
        return sized
    }

    /// For AppKit drawing that can't tint a template: the icon at a symbol's
    /// size, filled with `color`.
    public static func image(_ name: String, size: CGFloat, color: NSColor) -> NSImage? {
        guard let art = art(name) else { return nil }
        let side = (size * scale).rounded()
        return NSImage(size: NSSize(width: side, height: side), flipped: false) { rect in
            art.draw(in: rect)
            color.set()
            rect.fill(using: .sourceAtop)
            return true
        }
    }

    /// The same icon for a page the app draws in HTML, an agent task's,
    /// sized, and in the page's own ink rather than black.
    static func svg(_ name: String, side: Int, class kind: String? = nil) -> String? {
        svgs[name]?
            .replacingOccurrences(of: "width=\"24\" height=\"24\"", with: "\(kind.map { "class=\"\($0)\" " } ?? "")width=\"\(side)\" height=\"\(side)\"")
            .replacingOccurrences(of: "#000", with: "currentColor")
    }

