/// A menu line in the app's own drawing: its title, and beside it the mark
/// the same action wears in ⌘K, at the size a menu's symbol takes. With
/// none, a variant of the line above it, the title keeps the titles' column
/// all the same, as in the Mac's own menus.
extension Button where Label == SwiftUI.Label<Text, Image> {
    @MainActor public init(_ title: String, mark: String?, action: @escaping () -> Void) {
        self.init(action: action) { MenuMark.label(title, mark) }
    }

    @MainActor public init(_ title: String, mark: String?, role: ButtonRole?, action: @escaping () -> Void) {
        self.init(role: role, action: action) { MenuMark.label(title, mark) }
    }
}

extension Menu where Label == SwiftUI.Label<Text, Image> {
    @MainActor public init(_ title: String, mark: String?, @ViewBuilder content: () -> Content) {
        self.init(content: content) { MenuMark.label(title, mark) }
    }
}

/// The marks menu lines wear, and seeing that they show.
///
/// A line with no picture is drawn from the menu's edge while the others'
/// titles stand past their pictures, so one without a mark wears nothing as
/// wide as a mark, and its title keeps the column.
///
/// Stamped with the 26 SDK (Package.swift), the app gets its menu lines'
/// pictures drawn. From the 27 SDK on, macOS decides for itself and mostly
/// hides them unless a line asks (NSMenuItem.preferredImageVisibility), so
/// every line here asks now. An AppKit menu's lines ask as they are dressed
/// (PageView.dress); SwiftUI's menus have no way to, so theirs are asked
/// the moment SwiftUI adds them, before the menu is drawn: by the time it
/// begins tracking it is too late. SwiftUI hands the menu the very image it
/// was given, so a mark is known by being one of these, and no other
/// picture in any menu is touched.
@MainActor
public enum MenuMark {
    private static var made: [String: NSImage] = [:]
    private static var ours = Set<ObjectIdentifier>()

    /// A mark, or with none, nothing as wide as one.
    public static func image(_ mark: String?) -> NSImage {
        _ = watching
        let key = mark ?? ""
        if let hit = made[key] { return hit }
        let image = mark.flatMap(drawn)
            ?? NSImage(size: NSSize(width: side, height: side), flipped: false) { _ in true }
        image.isTemplate = true
        made[key] = image
        ours.insert(ObjectIdentifier(image))
        return image
    }

    private static var sites: [ObjectIdentifier: (source: NSImage, small: NSImage)] = [:]

    /// A site's own picture, a favicon, on a menu line: drawn in a mark's
    /// square and shown as the marks are, where macOS 27 would hide it.
    public static func picture(_ icon: NSImage) -> NSImage {
        _ = watching
        let key = ObjectIdentifier(icon)
        if let hit = sites[key], hit.source === icon { return hit.small }
        if sites.count > 64 {
            for kept in sites.values { ours.remove(ObjectIdentifier(kept.small)) }
            sites.removeAll()
        }
        let small = NSImage(size: NSSize(width: side, height: side), flipped: false) { rect in
            icon.draw(in: rect, from: .zero, operation: .sourceOver, fraction: 1)
            return true
        }
        sites[key] = (icon, small)
        ours.insert(ObjectIdentifier(small))
        return small
    }

    /// A mark's square: 16 points, a favicon's in a menu, in the icons' own
    /// 2-point pen: thinned to 1.5, a mark went grey and soft at 1x and its
    /// corner verb blurred (the Linear comparison, 2026-10-21).
    public static let side: CGFloat = 16

    private static func drawn(_ mark: String) -> NSImage? {
        guard let art = Glyphs.art(mark) else {
            return NSImage(systemSymbolName: mark, accessibilityDescription: nil)?
                .withSymbolConfiguration(.init(pointSize: 12, weight: .regular))
        }
        return NSImage(size: NSSize(width: side, height: side), flipped: false) { rect in
            art.draw(in: rect)
            return true
        }
    }

    public static func label(_ title: String, _ mark: String?) -> SwiftUI.Label<Text, Image> {
        SwiftUI.Label { Text(title) } icon: { Image(nsImage: image(mark)) }
    }

    /// A line of an AppKit menu in a mark, or in the blank, and shown.
    public static func put(_ mark: String?, on item: NSMenuItem) {
        item.image = image(mark)
        show(item)
    }

    /// Asks that a line's picture be drawn, where macOS 27 would hide it.
    public static func show(_ item: NSMenuItem) {
        #if compiler(>=6.4) // macOS 27's SDK (Xcode 27); Xcode 26 has no such ask
        guard #available(macOS 27, *), item.image != nil else { return }
        item.preferredImageVisibility = .visible
        #endif
    }

    private static let watching: Void = {
        NotificationCenter.default.addObserver(forName: NSMenu.didAddItemNotification, object: nil, queue: nil) { note in
            MainActor.assumeIsolated {
                guard let menu = note.object as? NSMenu,
                      let index = note.userInfo?["NSMenuItemIndex"] as? Int,
                      index < menu.numberOfItems, let item = menu.item(at: index),
                      let image = item.image, ours.contains(ObjectIdentifier(image))
                else { return }
                show(item)
            }
        }
    }()
}

/// Central's minus-large and cross-large as one shape, so the one can turn
/// into the other: the minus is the cross folded flat, its two strokes lying
/// on each other, and `open` swings them apart to ±45°, from the minus's 16
/// of the 24 to the cross's 19.8. Stroke it a twelfth of its side with round
/// caps, as the icons are drawn.
public struct MinusCross: Shape {
    /// 0 a minus, 1 a cross.
    public var open: CGFloat

    public init(open: CGFloat) { self.open = open }

    public var animatableData: CGFloat {
        get { open }
        set { open = newValue }
    }

    public func path(in rect: CGRect) -> Path {
        let unit = min(rect.width, rect.height) / 24
        let half = (8 + (7 * 2.squareRoot() - 8) * open) * unit
        let turn = Double.pi / 4 * Double(open)
        let dx = CGFloat(cos(turn)) * half, dy = CGFloat(sin(turn)) * half
        var path = Path()
        for sign: CGFloat in [1, -1] {
            path.move(to: CGPoint(x: rect.midX - dx, y: rect.midY - sign * dy))
            path.addLine(to: CGPoint(x: rect.midX + dx, y: rect.midY + sign * dy))
        }
        return path
    }
}

/// A symbol by name, drawn from `Glyphs` when there is an icon for it and by
/// the system otherwise. `size` is the point size the symbol would have been
/// set in; the color is the foreground style, as with any symbol.
public struct Symbol: View {
    let name: String
    var size: CGFloat
    var weight: Font.Weight = .medium
    /// The square it is drawn in, where not the one `size` gives.
    var side: CGFloat?
    /// Its line's width in points, where not the icon's own (Glyphs.art).
    var stroke: CGFloat?

    public init(_ name: String, size: CGFloat, weight: Font.Weight = .medium, side: CGFloat? = nil, stroke: CGFloat? = nil) {
        self.name = name
        self.size = size
        self.weight = weight
        self.side = side
        self.stroke = stroke
    }

    public var body: some View {
        let side = self.side ?? (size * Glyphs.scale).rounded()
        if let art = stroke.flatMap({ Glyphs.art(name, stroke: $0, side: side) }) ?? Glyphs.art(name) {
            Image(nsImage: art)
                .renderingMode(.template)
                .resizable()
                .frame(width: side, height: side)
        } else {
            Image(systemName: name).font(.system(size: size, weight: weight))
        }
    }
}
